package com.cenedu.backend.domain.problem.authoring.semantic.materialization;
import com.cenedu.backend.domain.problem.authoring.asset.*; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.entity.enums.AssetRole; import java.util.*;
 public final class SemanticAssetPlanFactory { public List<GeneratedAssetPlan> create(List<DiagramSpecV1> specs){var out=new ArrayList<GeneratedAssetPlan>();for(var s:specs){var elements=new ArrayList<String>();elements.add(s.kind().name());out.add(new GeneratedAssetPlan(s.assetKey(),s.kind()==DiagramKind.DATA_TABLE?AssetRole.TABLE:AssetRole.FIGURE,AssetProductionMode.STRUCTURED_RENDER,AssetOutputFormat.SVG,s.assetKey(),new AssetGenerationSpecification(1,"deterministic "+s.kind().name(),elements,List.of("script","http","javascript"),Map.of(),s)));}return List.copyOf(out);} }
